Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Cards.Card host) { return; }
    if (view.Card is not Orc.Cards.Card played || !object.ReferenceEquals(played, host)) { return; }

    var amount = Orc.Game.Cards.KeywordRules.GetKeywordValue(host, Orc.Game.Cards.KeywordIds.Intelligence) ?? 0;
    await Orc.Game.Cards.IntelligenceRules.InvokePendingRevealAsync(host, amount, host.Engine, ct);
};
